css.value:
* {
    font-size: var(--Typography-Size-Identifier-identifier-xxl, 32px);
    font-style: normal;
    font-weight: 400;
    line-height: normal;
}

targets.clientTransformScript:
javascript(/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	return {
		propName: "selectedNode",
		value: event.context.item.value
	};
})

